function reviewedObservationSourceInput(file,text){const r=observationSourceRecords.find(r=>r.target===file);if(!r)return text;const hash=v=>createHash('sha256').update(v).digest('hex'),pin=hash(text);if(pin===r.parent_sha256)return text;assert.equal(pin,r.sha256,'unreviewed observer source input');for(const h of [...r.hunks].reverse()){assert.equal(hash(text),h.after_state_sha256);assert.equal(text.slice(h.start_utf16,h.start_utf16+h.after.length),h.after);text=text.slice(0,h.start_utf16)+h.before+text.slice(h.start_utf16+h.after.length);assert.equal(hash(text),h.before_state_sha256)}assert.equal(hash(text),r.parent_sha256);return text}
