for(const row of fixed.targets)test('exact Root-v2 parent inverse: '+row.target,()=>{let text=read(row.target);assert.equal(sha(text),row.sha256);for(const h of [...row.hunks].reverse()){assert.equal(sha(text),h.after_state_sha256);assert.equal(text.slice(h.start_utf16,h.start_utf16+h.after.length),h.after);text=text.slice(0,h.start_utf16)+h.before+text.slice(h.start_utf16+h.after.length);assert.equal(sha(text),h.before_state_sha256)}assert.equal(sha(text),row.parent_sha256)});
const parse=file=>{const text=read(file),ast=ts.createSourceFile(file,text,ts.ScriptTarget.Latest,true);assert.equal(ast.parseDiagnostics.length,0);return{text,ast}};
function actual(file,name,ports={}){const{text,ast}=parse(file),node=ast.statements.find(n=>n.name?.text===name);assert(node,name);const start=node.getStart(ast),edits=[];function walk(n){if((ts.isParameter(n)||ts.isVariableDeclaration(n)||ts.isFunctionDeclaration(n))&&n.type){const colon=text.lastIndexOf(':',n.type.pos);assert(colon>=n.pos);edits.push({start:colon,end:n.type.end,after:''})}if(ts.isCallExpression(n)&&n.expression.kind===ts.SyntaxKind.ImportKeyword){assert.equal(n.arguments.length,1);assert(ts.isStringLiteral(n.arguments[0]));edits.push({start:n.getStart(ast),end:n.end,after:'modulePort('+JSON.stringify(n.arguments[0].text)+')'})}n.forEachChild(walk)}walk(node);const outer=edits.filter((r,i)=>!edits.some((p,j)=>j!==i&&p.start<=r.start&&p.end>=r.end&&(p.start<r.start||p.end>r.end))).sort((a,b)=>b.start-a.start);let code=text.slice(start,node.end);for(const e of outer)code=code.slice(0,e.start-start)+e.after+code.slice(e.end-start);code=code.replace(/^export /,'');return vm.runInNewContext('('+code+')',{URL,...ports},{timeout:1000})}
