test('unselected Staff wrapper refuses before optional code loading',async()=>{let loaded=0;const run=actual('services/pg-api/src/native-employee-staff084-profile.mjs','inspectStaffCompositeStatisticsSchema',{bad(){throw Error('refused')},selectNativeEmployeeStaff084Profile:()=>null,modulePort:async()=>{loaded++}});await assert.rejects(run({},{}),/refused/);assert.equal(loaded,0)});
test('actual selected Staff API profile forwards exact server selection to unchanged named statistics audit',async()=>{const pool={},selected={},calls=[],run=actual('services/pg-api/src/employee-staff084-profile.mjs','inspectEmployeeStaff084StatisticsPool',{modulePort:async file=>{assert.equal(file,'./staff084-home-knowledge-stats-audit.ts');calls.push(file);return{inspectStaff084OriginalHomeKnowledgeStatisticsSchema:async(db,s)=>{assert.equal(db,pool);assert.equal(s,selected);calls.push('inspect');return'installed'}}}});assert.equal(await run(pool,selected),'installed');assert.deepEqual(calls,['./staff084-home-knowledge-stats-audit.ts','inspect'])});
test('actual selected Quality wrapper validates full profile before named statistics load',async()=>{const pool={},env={},calls=[],run=actual('services/pg-api/src/native-employee-quality089-profile.mjs','inspectNativeQuality089StatisticsSchema',{selectNativeEmployeeQuality089Profile:input=>{assert.equal(input,env);calls.push('select')},inspectNativeEmployeeQuality089Profile:async(db,input)=>{assert.equal(db,pool);assert.equal(input,env);calls.push('whole_profile')},modulePort:async file=>{assert.equal(file,'./native-home-knowledge-stats-audit.ts');calls.push(file);return{inspectQuality089OriginalHomeKnowledgeStatisticsSchema:async db=>{assert.equal(db,pool);calls.push('named_stats');return'installed'}}}});assert.equal(await run(pool,env),'installed');assert.deepEqual(calls,['select','whole_profile','./native-home-knowledge-stats-audit.ts','named_stats'])});
for(const phase of ['select','whole_profile','named_stats'])test('Quality '+phase+' refusal cannot fall back or bypass',async()=>{const error=Error('fixed '+phase),calls=[],run=actual('services/pg-api/src/native-employee-quality089-profile.mjs','inspectNativeQuality089StatisticsSchema',{selectNativeEmployeeQuality089Profile:()=>{calls.push('select');if(phase==='select')throw error},inspectNativeEmployeeQuality089Profile:async()=>{calls.push('whole_profile');if(phase==='whole_profile')throw error},modulePort:async()=>({inspectQuality089OriginalHomeKnowledgeStatisticsSchema:async()=>{calls.push('named_stats');if(phase==='named_stats')throw error}})});let caught;try{await run({},{})}catch(e){caught=e}assert.equal(caught,error);assert.deepEqual(calls,phase==='select'?['select']:phase==='whole_profile'?['select','whole_profile']:['select','whole_profile','named_stats'])});
test('Native uses one selected callback only after full profile preflight and passes it to both startup paths',()=>{const source=read('services/pg-api/src/native-server.ts');assert(source.indexOf('const originalStatisticsInspector=')>source.indexOf('if(!await inspectNativeEmployeeStaff084Profile(business,adapter(authPool),env))'));assert(source.includes('inspectSelectedSchema:originalStatisticsInspector'));assert(source.includes('inspectStatisticsSchema:originalStatisticsInspector'));assert(source.includes("(await import('./native-employee-quality089-profile.mjs')).inspectNativeQuality089StatisticsSchema(pool,env)"));assert(source.includes('inspectStaffCompositeStatisticsSchema(pool,env)'))});
for(const [file,expected]of [['tests/helpers/staff084-hosted-fixture.mjs','nativeProfile.inspectStaffCompositeStatisticsSchema(pool,runtimeEnv)'],['tests/helpers/quality089-hosted-fixture.mjs',"(await import('../../services/pg-api/src/native-employee-quality089-profile.mjs')).inspectNativeQuality089StatisticsSchema(pool,runtimeEnv)"]])test('hosted fixture injects exact selected audit '+file,()=>{const text=read(file);assert(text.includes('inspectStatisticsSchema:'));assert(text.includes(expected));assert(text.includes('env:{...runtimeEnv,AGENT_STUDIO_PG18_ORIGINAL_HOME_ENABLED:\'true\'}'))});
